// generated by gemini-3.5-flash-lite for PR #5992 (round 0): json_view_multiple_gets_parity
// intent: Verify sequence of calls to get<int>() and get<std::int64_t>() demonstrating mixed behavior on the same boolean view.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    auto doc = nlohmann::json_document::parse("true");
    auto view = doc.root();
    
    try {
        std::cout << "get<int>(): " << view.get<int>() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "get<int> threw: " << e.what() << std::endl;
    }
    
    try {
        std::cout << "get<std::int64_t>(): " << view.get<std::int64_t>() << std::endl;
    } catch (const nlohmann::json::type_error& e) {
        std::cout << "get<std::int64_t> threw type_error as expected" << std::endl;
    } catch (const std::exception& e) {
        std::cout << "get<std::int64_t> threw other: " << e.what() << std::endl;
    }
    return 0;
}
